<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo html_escape($title); ?></title>
<style>body{margin:0;font-family:Arial,sans-serif;background:linear-gradient(135deg,#0e6f5b,#173b73 58%,#f97316);min-height:100vh;display:grid;place-items:center;padding:20px}.card{max-width:760px;width:100%;background:#fff;border-radius:18px;box-shadow:0 24px 70px rgba(0,0,0,.28);overflow:hidden}.head{padding:26px;background:#173b73;color:#fff}.body{padding:28px}.empty{text-align:center;padding:28px;border:1px dashed #cbd5e1;border-radius:14px;background:#f8fafc}.icon{font-size:52px}.btn{display:inline-block;padding:11px 18px;border-radius:8px;text-decoration:none;font-weight:700;background:#169179;color:#fff;margin:6px}.btn.alt{background:#f97316}.meeting{border:1px solid #e5e7eb;border-radius:12px;padding:16px;margin:12px 0}</style></head><body><div class="card"><div class="head"><h1 style="margin:0">Smart Choice Video Meetings</h1><p style="margin:8px 0 0">One shared meeting link keeps every invited participant in the same room.</p></div><div class="body">
